import {WIKI_LESSONS,type WikiLesson} from './cad-wiki-lessons';
import {WIKI_EXAMPLES,type WikiExampleLesson} from './cad-wiki-examples';
export interface WikiExample extends WikiExampleLesson {title:string;files?:Record<string,string>;note?:string;preview?:boolean}
export interface WikiTopic {id:string;title:string;category:string;symbols:string[];summary:string;syntax:string;parameters:Array<[string,string]>;lesson:WikiLesson;body:string[];tips:string[];examples:WikiExample[];related:string[];status?:string;source?:string}
const ex=(title:string,files?:Record<string,string>):WikiExample=>({title,...WIKI_EXAMPLES[title],files});
const topic=(id:string,title:string,category:string,symbols:string[],summary:string,syntax:string,parameters:Array<[string,string]>,body:string[],tips:string[],examples:WikiExample[],related:string[],status?:string):WikiTopic=>({id,title,category,symbols,summary,syntax,parameters,lesson:WIKI_LESSONS[id],body,tips,examples,related,status});
export const WIKI_TOPICS:WikiTopic[]=[
topic('start','Start here: code to a solid','Getting started',[],'Build a printable part by combining simple solids and subtracting cutters.','shape();\noperation() { shape(); other_shape(); }',[],[
'OpenSCAD describes geometry rather than recording mouse gestures. Modules create shapes; functions calculate values. A semicolon finishes a statement. Braces group child statements. Transformations and operations act on the children immediately after them.',
'In RetroPaint, one coordinate unit is one millimetre. X and Y span the drawing plane; Z is height. Positive rotations use the right-hand rule. Most angles are degrees. A cube starts at the origin unless center=true; a sphere is always centred there.',
'Start with a cube, add a cylinder that passes right through it, and put both inside difference(). The first child is the material to keep; every later child is a cutter. Preview calculates a closed solid. Add to scene commits it; Update selected replaces a selected script model while retaining its placement.',
'The examples in this wiki run in an isolated preview. They do not replace your draft, add objects, or change the scene. Copy code when you want to use an example in your own project.'],['If a 2D shape is your final result, extrude it before adding it to the workshop.','Save Project preserves the code and dependencies; Save .scad exports only the file currently being edited.'],[ex('Your first drilled block')],['coordinates','workflow','difference','linear-extrude','recipe-flange']),
topic('workflow','Code studio, files and saving','Getting started',[],'Understand Preview, Auto preview, entry scripts, library editing, cancellation and saving.','Preview: F5 or Ctrl/Cmd+Enter\nEntry script: the file to render\nEdit file: the file shown in the editor',[],[
'Preview runs the official OpenSCAD engine in a local browser worker. It produces rendered geometry, like desktop F6, even though the button is named Preview. Auto preview starts when enabled and rebuilds after edits. Cancel render stops the current job. The previous model may remain visible while marked as stale; Add and Update stay disabled until the new render succeeds.',
'Open .scad loads a standalone source. For a project with include/use statements or imported geometry, use Project files & libraries → Open folder. Relative directories are retained. Select the Entry script that produces the final model. Edit file lets you change a helper or library while continuing to render the main entry.',
'Add files supplies extra assets or fonts. Use folder loading when paths matter. Missing dependencies stop the render. Project-local libraries take precedence over bundled libraries. Paths are relative to the referring source, with the project root and its libraries directory also searched for libraries.',
'Parameters expose unique top-level literal numeric constants. Expressions, duplicates and module-local variables stay in code. Parser diagnostics select the relevant project file and line. Changes remain a session draft until applied or saved; merely reading help or previewing a wiki example does not save a model.'],['Save Project after applying changes to retain the entire model and all supplied files.','Absolute paths from another computer must be converted to relative project paths.'],[ex('A project with a helper',{'parts/post.scad':'// Reusable post: h is the caller-supplied height in mm.\nmodule post(h) {\n  cylinder(h=h,r=4,$fn=32); // Base on Z=0; radius stays 4 mm.\n}'})],['include-use','limits','diagnostics']),
topic('coordinates','Coordinates, order and useful tolerances','Getting started',[],'Know where a shape is and why operation order changes the result.','translate([x,y,z]) rotate([rx,ry,rz]) shape();',[],[
'Read a chain from the shape outwards. translate([20,0,0]) rotate([0,0,45]) cube(10) first rotates the cube around the origin, then moves it. Reversing the transforms rotates the translation too, moving the cube around a circle.',
'Use center=true for symmetric parts, mirrored features and rotations around the middle. For a box that rests on Z=0, leave center=false or translate a centred box upward by half its height. A 2D profile lives in XY; extrude it before tilting it into 3D.',
'Boolean solids should overlap by a small amount. A cutter exactly flush with a face can leave numerical ambiguity. Extend through-cut tools slightly above and below the part. A joining boss should enter the parent by a small distance rather than merely touch it. Modelling tolerance and physical printer clearance are different: choose the latter for your actual process.'],['Point contact and edge contact do not make a robust printable union.','Manifold geometry has a consistent closed surface; intersecting or zero-area faces may be rejected.'],[ex('A boss with overlap')],['translate','rotate','union','recipe-pocket']),
topic('cube','cube — boxes and blocks','3D primitives',['cube'],'Create a cube or rectangular box.','cube(size=1, center=false);\ncube([width,depth,height], center=false);',[['size','One positive number gives equal sides; a three-number vector gives X, Y and Z lengths.'],['center','false: spans from [0,0,0] into positive coordinates. true: extends half the size in each direction.']],[
'Boxes are useful as stock material, square holes, cutting planes and bases. A centred box is easier to rotate or intersect symmetrically. A non-centred box makes bottom and corner locations straightforward.'],['Zero thickness does not create a solid. Use square() for a flat profile.'],[ex('A centred rectangular block')],['square','translate','difference']),
topic('sphere','sphere — balls and rounded cutters','3D primitives',['sphere'],'Create a ball centred on the origin.','sphere(r=radius);\nsphere(d=diameter);',[['r / d','Choose radius or diameter, not both.'],['$fn / $fa / $fs','Control the polygonal approximation.']],[
'A sphere is tessellated into a finite mesh. It can be stretched with scale() to form an ellipsoid, subtracted to make a bowl, or used in a Minkowski sum to round corners. Increase resolution only as far as your output needs.'],['Unlike cube() and cylinder(), sphere() has no center parameter.'],[ex('An ellipsoid')],['resolution','scale','minkowski']),
topic('cylinder','cylinder — cylinders, cones and frustums','3D primitives',['cylinder'],'Create a circular solid along Z, optionally tapering between two radii.','cylinder(h=height, r=radius, center=false);\ncylinder(h=height, r1=bottom, r2=top, center=false);',[['h','Height along Z.'],['r / d','Constant radius or diameter.'],['r1, r2 / d1, d2','Lower and upper sizes. One end may be zero to create a pointed cone.'],['center','false: bottom at Z=0. true: extends equally above and below Z=0.'],['$fn','A low integer can deliberately create a prism; $fn=6 makes a hexagon.']],[
'Use cylinders for shafts, holes, bosses and washers. Rotate a cylinder by 90 degrees around X or Y for a sideways bore. To make a tube, subtract a smaller cylinder that extends beyond both ends.'],['Polygonal circles lie inside the ideal circle at their flat sides; check hole clearance rather than assuming the nominal radius is a perfect fit.'],[ex('A tapered hollow sleeve')],['rotate','resolution','recipe-flange']),
topic('polyhedron','polyhedron — explicit mesh solids','3D primitives',['polyhedron'],'Build a closed polyhedral solid from vertices and face loops.','polyhedron(points=[...], faces=[...], convexity=1);',[['points','A list of [x,y,z] vertices.'],['faces','Each face is a list of vertex indices, starting at zero.'],['convexity','A desktop preview ray-crossing hint; it does not repair a mesh.']],[
'Faces must form a closed, non-self-intersecting surface. Every edge must belong to two faces. OpenSCAD face order uses the left-hand convention: when viewed from outside a face, its vertices run clockwise. Concave faces or non-planar loops are easier to reason about when explicitly triangulated.',
'Use shared vertex indices at joins. A missing face makes an open shell, which is not a printable solid. If only a 2D outline is needed, polygon() plus extrusion is simpler and safer.'],['The older triangles parameter is deprecated; use faces.','Inspect a low-detail mesh before generating thousands of faces.'],[ex('A square-based pyramid')],['polygon','linear-extrude','diagnostics']),
topic('square','square — rectangular profiles','2D profiles',['square'],'Create a flat rectangle in XY, ready for extrusion or booleans.','square(size=1, center=false);\nsquare([width,height], center=false);',[['size','A scalar gives equal sides; [x,y] gives two dimensions.'],['center','Centre the profile around the origin when true.']],[
'2D operations work on areas rather than surfaces. A square has no thickness until linear_extrude() is applied. Use it as the stock for a flat plate, as a subtractive slot, or as the generating profile for a revolved ring.'],['Do not mix 2D and 3D children in one boolean operation.'],[ex('A rectangular plate')],['linear-extrude','offset','circle']),
topic('circle','circle — round profiles and regular polygons','2D profiles',['circle'],'Create a circular area in XY, with controllable segmentation.','circle(r=radius);\ncircle(d=diameter, $fn=segments);',[['r / d','Radius or diameter.'],['$fn','Segment count; 3 gives a triangle, 6 a hexagon.']],[
'Extruding a circle gives a cylinder. Translating a small circle away from the origin and revolving it gives a torus. Circle profiles also work well with hull() to make rounded slots and rounded rectangles.'],['The default profile is centred on [0,0].'],[ex('A hexagonal spacer')],['hull','rotate-extrude','resolution']),
topic('polygon','polygon — outlines and holes','2D profiles',['polygon'],'Define a planar area from points and optional boundary paths.','polygon(points=[[x,y],...], paths=[[index,...],...], convexity=1);',[['points','All coordinates in a shared list.'],['paths','Optional loops of indices into points; multiple loops can describe holes. Omit for a single outline.'],['convexity','Desktop preview hint; not a smoothing or repair setting.']],[
'A boundary closes automatically; you do not need to repeat its first point. Keep each loop simple and avoid overlapping edges or self-intersection. For ordinary holes, a 2D difference of simple profiles is often clearer than manually managing nested paths.',
'Use comprehensions to generate points from equations, then extrude the profile. For a revolved profile, X becomes radius and Y becomes height; keep it on one side of the rotation axis.'],['Paths refer to indices, not to coordinate pairs.'],[ex('An extruded pentagonal profile')],['comprehensions','linear-extrude','rotate-extrude']),
topic('text','text — raised and engraved lettering','2D profiles',['text'],'Turn a string into a 2D outline, then extrude it to add or cut letters.','text(text, size=10, font, halign="left", valign="baseline", spacing=1, direction="ltr", language="en", script="latin");',[['text','String to lay out. Use str() to incorporate numeric values.'],['size','Nominal text size, not a promise of exact cap height.'],['font','Family and optional style, such as "Noto Sans:style=Regular". Add TTF/OTF files for other fonts.'],['halign / valign','Horizontal left/center/right; vertical baseline/top/center/bottom.'],['spacing','Character spacing multiplier.'],['direction, language, script','Text shaping controls for writing systems.'],['em','Alternative em-size control in this newer engine. It uses the font’s design em rather than the historical size convention; prefer either size or em consistently in text and metrics.'],['$fn / $fa / $fs','Affect curve tessellation; very high values can make lettering expensive.']],[
'Text produces an area. Use linear_extrude() to make it solid. For raised lettering, overlap its extrusion with the supporting plate. For engraving, place the cutter slightly above the face and extend it downward into the part.',
'Noto Sans is bundled. A font unavailable in the virtual filesystem may be substituted, changing letter shape and spacing. Use textmetrics() when you need the actual rendered bounds.'],['Tiny detached dots and thin strokes may be difficult to print even when the mesh is valid.'],[ex('Raised label')],['textmetrics','str','recipe-label']),
topic('projection','projection — flatten or slice a solid','2D profiles',['projection'],'Convert a 3D shape into a 2D area for further profile work.','projection(cut=false) solid();',[['cut=false','Project the complete shape onto XY, forming its silhouette.'],['cut=true','Take the section where the solid intersects Z=0. Move the solid to choose a different section.']],[
'Projection is useful for templates, outlines and producing a profile from a complex solid. Its result is 2D; wrap it in linear_extrude() to add it to the workshop. A cut plane that misses the solid produces nothing.'],['Projection discards height. Rotating a shape before projection changes the outline.'],[ex('Extrude a sliced sphere outline')],['linear-extrude','translate']),
topic('linear-extrude','linear_extrude — lift, taper and twist a profile','Make solids from profiles',['linear_extrude'],'Turn a 2D area into a solid with height, optional twist and taper.','linear_extrude(height, center=false, twist=0, scale=1, slices, segments, convexity=1, v=[0,0,1]) profile();',[['height','Extrusion height; use a positive value for a dependable solid.'],['center','Distribute extrusion around the profile plane when true.'],['twist','Total twist in degrees. Positive twist follows OpenSCAD’s extrusion convention; preview its handedness before designing a mating thread.'],['scale','Final cross-section scale, scalar or [x,y]. It interpolates from 1 at the base.'],['slices / segments','Vertical subdivisions and profile subdivision controls for curved/twisted surfaces.'],['v','Extrusion vector in this newer engine; it must have a positive Z component. With height specified it supplies direction; without height its length supplies extrusion length. Rotate a standard extrusion for portable older scripts.'],['convexity','Preview hint, not mesh detail.']],[
'All child geometry should be 2D in XY. Transform the 2D outline first to change its cross-section; transform the completed extrusion to place it in 3D. Difference and union between 2D profiles can build hollow cross-sections before extrusion.',
'More slices can make a twisted part smoother, but they add triangles. Excessive twist with a wide outline can self-intersect. A taper to zero converges to a point; asymmetric scaling can create fragile tips.'],['A 2D translate in Z is not a way to set the extrusion’s elevation. Translate the finished extrusion instead.'],[ex('Twisted, tapered column')],['polygon','offset','rotate-extrude']),
topic('rotate-extrude','rotate_extrude — rings, bowls and turned parts','Make solids from profiles',['rotate_extrude'],'Sweep a 2D cross-section around the Z axis.','rotate_extrude(angle=360, start=0, convexity=2, $fn=64) profile();',[['angle','Sweep angle in degrees; 360 closes a complete revolution.'],['start','Starting angle, supported by the bundled newer engine. Specify it explicitly for predictable partial sweeps.'],['profile X / Y','Profile X becomes radial distance; profile Y becomes Z height.'],['$fn / $fa / $fs','Control facets around the sweep.']],[
'Draw the cross-section in XY as if X were radius and Y were height. Keep the whole area on one side of X=0. An outline may touch the axis, but crossing it can create invalid geometry. A profile away from the axis leaves a central hole.',
'The sweep rotates the profile, not a 3D object. For a torus, translate a circle away from the axis and revolve it. For a bowl, describe the outside, lip, inside and bottom in one closed polygon.'],['A full revolution can merge points on the axis. RetroPaint removes collapsed transfer triangles while still validating the closed result.'],[ex('A hollow bowl'),ex('A torus')],['polygon','circle','recipe-bowl']),
topic('union','union — join material','Combine and cut',['union','group'],'Combine overlapping children into a single resulting volume.','union() { first(); second(); }\ngroup() { first(); second(); }',[],[
'A union keeps every region covered by any child. Overlapping solids fuse; separated solids remain separate components in the same result. Use slight overlap when making bosses, feet or lettering on a base.',
'Multiple top-level shapes and ordinary for loops normally combine their children. An explicit union is valuable when you want several shapes treated as one child of difference(). group() is a grouping module; use union() when your intent is geometric combination.'],['Face-only, edge-only and point-only contact are less robust than overlap.'],[ex('A fused base and boss')],['difference','intersection','coordinates']),
topic('difference','difference — holes, slots and pockets','Combine and cut',['difference'],'Remove every child after the first from the first child.','difference() { material(); cutter1(); cutter2(); }',[],[
'Order matters. Only the first child is stock; everything else is subtractive. Wrap several stock pieces in union() when they should all survive before the cuts. A cutter may be any valid solid, including imported geometry.',
'For a through-hole, extend the cutter past both sides. For a pocket, let the cutter enter from the outside but stop above the bottom. A cutter that misses the material does nothing. A cutter that consumes all the material leaves an empty result.'],['OpenSCAD does not automatically infer “hole” from a shape’s colour or name. It must be a child of difference().'],[ex('A slot and a round bore')],['union','recipe-pocket','recipe-flange']),
topic('intersection','intersection and intersection_for — common volume','Combine and cut',['intersection','intersection_for'],'Keep only material shared by all participating shapes.','intersection() { a(); b(); }\nintersection_for(i=[...]) shape(i);',[],[
'Intersection is useful for cropping shapes, constraining a pattern to a boundary and forming lenses. If any participating child has no shared region with the others, the result is empty.',
'intersection_for() intersects each iteration. An ordinary for loop inside intersection() is usually one combined child, so it does not mean “intersect every iteration”. Use intersection_for() for that intent.'],['Check placement before blaming an empty intersection on the engine.'],[ex('A rounded cube'),ex('Intersect rotated bars')],['for','union','difference']),
topic('hull','hull — the convex envelope','Combine and cut',['hull'],'Wrap children in the smallest convex region enclosing them.','hull() { a(); b(); ... }',[],[
'Hull bridges gaps and removes concavities. Two circles make a rounded slot; four corner circles make a rounded rectangle. Two spheres at different positions make a capsule. It is not a general loft: the envelope is always convex.',
'When making a flat plate, hull 2D profiles and extrude once. This is usually simpler and cheaper than hulling high-resolution 3D cylinders.'],['A hull fills holes and recesses inside the envelope. Subtract them afterwards.'],[ex('A capsule plate')],['minkowski','linear-extrude','recipe-rounded']),
topic('minkowski','minkowski — grow a shape with another shape','Combine and cut',['minkowski'],'Combine every point of one shape with every point of the other, often to round edges.','minkowski() { base(); kernel(); }',[['base and kernel','Both children must have the same dimensionality. Their extents add.']],[
'A box plus a sphere produces rounded edges in all directions. A 2D rectangle plus a circle rounds its corners. The kernel’s position matters: a centred sphere grows equally in every direction; a cylinder based at Z=0 also shifts the resulting vertical extent.',
'This can be much more expensive than hull or offset. Reduce kernel resolution while designing and account for the added dimensions. To get an outside width W with a spherical radius r, start from a box width W−2r.'],['For 2D rounding, offset(r=...) is usually the first tool to try.'],[ex('Rounded stock')],['offset','hull','recipe-rounded']),
topic('translate','translate — move geometry','Transform geometry',['translate'],'Move a shape without changing its size or orientation.','translate([x,y,z]) solid();\ntranslate([x,y]) profile();',[['v','Offset vector in the current coordinate system.']],[
'Translate changes all points by the same offset. Nested translations add. Use it before a rotation to orbit a shape around the origin, or after a rotation to rotate a shape locally and then place it.'],['A vector supplies coordinates; it is not three separate arguments.'],[ex('Two spaced posts')],['coordinates','rotate','for']),
topic('rotate','rotate — orient or orbit','Transform geometry',['rotate'],'Rotate around the origin using Euler angles or an axis and angle.','rotate([xDegrees,yDegrees,zDegrees]) shape();\nrotate(a=degrees, v=[x,y,z]) shape();',[['Euler vector','Applied in X, then Y, then Z order.'],['a / v','Angle and axis direction. v need not be unit length, but must not be zero.']],[
'Rotations use degrees and the right-hand rule. The origin is the pivot. To rotate around another point p, translate by −p, rotate, then translate by p. OpenSCAD nesting writes those operations in the reverse visual order because the innermost operation happens first.'],['Rotation order is not interchangeable.'],[ex('A horizontal through-bore')],['coordinates','translate','atan2']),
topic('scale','scale — stretch and reflect','Transform geometry',['scale'],'Multiply coordinates by independent factors.','scale([sx,sy,sz]) solid();',[['factors','1 leaves an axis unchanged; 2 doubles it; 0 collapses it; a negative value reflects across that axis.']],[
'Scaling happens relative to the origin. Scale a centred shape to keep its centre fixed. Non-uniform scaling of a sphere makes an ellipsoid, while scaling a cylinder changes its round cross-section to an ellipse.'],['Avoid zero factors for solid output. Use projection() to intentionally reduce dimensionality.'],[ex('An elliptical puck')],['resize','mirror','sphere']),
topic('resize','resize — set final bounding dimensions','Transform geometry',['resize'],'Resize geometry according to its bounding box rather than explicit scale factors.','resize([newX,newY,newZ], auto=false) shape();',[['new size','Requested bounding lengths. Zero means leave that dimension unspecified.'],['auto','true proportionally scales unspecified dimensions; a boolean vector controls axes individually.']],[
'Resize must evaluate the child geometry’s bounds, so it is heavier than scale(). It is useful for imported shapes whose original dimensions you do not know. Use a single specified axis plus auto=true to preserve proportions.'],['Resizing the geometry also scales holes and wall thicknesses.'],[ex('Set a ball’s width proportionally')],['scale','import']),
topic('mirror','mirror — reflect in a plane','Transform geometry',['mirror'],'Reflect geometry across a plane through the origin.','mirror([nx,ny,nz]) shape();',[['normal','Direction perpendicular to the mirror plane. [1,0,0] reflects X; [0,1,0] reflects Y.']],[
'Mirror produces only the reflected child, not the original plus a copy. Use union() to keep both. To mirror about an offset plane, move the geometry to that plane’s local origin, mirror, and move it back.'],['The vector describes the plane’s normal, not a target position.'],[ex('Paired mirrored tabs')],['union','translate','scale']),
topic('multmatrix','multmatrix — affine transformation matrices','Transform geometry',['multmatrix'],'Apply a 4×4 transformation matrix to geometry.','multmatrix([[a,b,c,tx],[d,e,f,ty],[g,h,i,tz],[0,0,0,1]]) shape();',[['upper-left 3×3','Rotation, scale or shear.'],['last column','Translation components.'],['last row','Use [0,0,0,1] for ordinary affine transforms.']],[
'Each point is treated as [x,y,z,1] and multiplied by the matrix. This is useful for a custom coordinate frame or a shear that is not expressed by the simpler transform modules. Matrix multiplication order matters just like nested transforms.'],['An invertible matrix preserves solid dimensionality; a singular matrix can flatten the shape.'],[ex('Shear a block')],['operators','scale','rotate']),
topic('color','color and visual modifiers','Transform geometry',['color','#','%','!','*'],'Understand which OpenSCAD visual controls affect the rendered solid.','color("red", alpha=1) shape();\ncolor([r,g,b,a]) shape();\n#shape(); %shape(); !shape(); *shape();',[['color','Named colour, supported hexadecimal colour string or 0–1 RGBA vector.'],['#','Highlight a child in desktop preview.'],['%','Display background geometry in desktop preview; excluded from final solid output.'],['!','Select a subtree as the root for debugging.'],['*','Disable a subtree.']],[
'RetroPaint transfers rendered geometry through STL, which has no material colours. color() does not become per-face workshop colour, and # is not a visible highlight here. Set the resulting object’s colour in the workshop. Background geometry marked % is not material in the final render.',
'Do not rely on transparency to cut holes. Use difference() for geometry. Avoid ! in reusable libraries because it changes which subtree is shown.'],['Desktop F5 screenshots may differ from this rendered-solid view.'],[ex('Colour does not change the solid')],['limits','difference','diagnostics'],'Visual effects are not preserved in STL'),
topic('fill','fill — remove holes from a 2D profile','2D profiles',['fill'],'Fill interior holes while retaining the outside outline.','fill() profile();',[],['Unlike hull(), fill() does not replace the outer outline with a convex envelope. It removes enclosed holes from 2D child geometry. This is useful when an imported silhouette has interior openings that should not appear in a backing plate.','Apply fill before extrusion. It is a newer engine operation, so a desktop installation with an older release may not recognise it.'],['Use difference to put deliberately designed holes back afterwards.'],[ex('Fill a ring to make a backing disk')],['hull','import','linear-extrude']),
topic('offset','offset — grow or shrink a 2D outline','2D profiles',['offset'],'Expand, contract or round a planar profile before extrusion.','offset(r=radius) profile();\noffset(delta=distance, chamfer=false) profile();',[['r','Round offset distance. Positive expands; negative contracts.'],['delta','Straight-edge offset distance.'],['chamfer','With delta, bevel joins instead of retaining sharp extended intersections.']],[
'Offsets work on 2D geometry only. A positive offset grows the outside and shrinks holes; a negative offset does the reverse. Features narrower than the offset can disappear. Two opposite offsets can round corners without changing broad dimensions, but small details may be lost.',
'A hollow wall can be constructed as difference() between an outline and a smaller offset of the same outline. Check that enough material remains after shrinking.'],['Offsetting a 3D solid is not supported; use 2D profiles or carefully designed Minkowski operations.'],[ex('A rounded frame')],['minkowski','linear-extrude','recipe-box']),
topic('resolution','Resolution, facets and convexity','Getting started',['$fn','$fa','$fs','convexity'],'Balance smoothness, accuracy and rendering cost.','$fn=48;\n$fa=12;\n$fs=2;',[['$fn','When positive, requests a fixed segment count. Zero lets $fa and $fs govern tessellation.'],['$fa','Minimum angular step in degrees for automatic segmentation.'],['$fs','Minimum segment size in model units for automatic segmentation.'],['convexity','Desktop preview visibility hint, not the number of segments or a repair switch.']],[
'These special variables can be global or local to a shape call. A lower $fa or $fs generally allows more segments when $fn is zero. A high $fn multiplies the cost of spheres, text, sweeps and boolean operations.',
'Set resolution deliberately for the final object. A nominal circular hole is represented by a polygon; higher resolution reduces the difference but costs triangles. Using $fn=6 intentionally creates a hexagonal profile rather than a smooth circle.'],['RetroPaint currently accepts at most 200,000 triangles per transferred solid.'],[ex('Same radius, different profiles')],['circle','sphere','limits']),
topic('variables','Variables, scope and constants','Language',['undef','PI'],'Use parameters and understand OpenSCAD’s declarative assignment rules.','width=30;\nvalue=condition ? yes : no;\nlet(local=width/2) shape();',[['undef','Represents an undefined value. Test with is_undef().'],['PI','The mathematical constant π. Trigonometric functions still use degrees.']],[
'OpenSCAD is declarative: a variable is not a mutable accumulator. Reassigning a name in the same scope does not behave like successive updates in an imperative language; the final assignment can govern earlier uses in that scope. Prefer unique names or let() for intermediate values.',
'Braces introduce local scopes in many constructs. Module parameters provide defaults that callers may override. Special variables beginning with $ are dynamically passed through child calls and are useful for settings such as resolution. Ordinary variables use lexical scoping.',
'Values include numbers, booleans, strings, lists, undef, functions and some built-in metric objects. Use type tests when a reusable function accepts several forms.'],['Do not write n=n+1 expecting a loop counter update. Generate a range or use recursion/comprehensions.'],[ex('A parameter-driven block')],['let','functions','types','operators']),
topic('operators','Operators, vectors and matrices','Language',['+','-','*','/','%','^','<','<=','>','>=','==','!=','&&','||','!','?:'],'Calculate sizes, compare values and select conditional expressions.','a+b; a-b; a*b; a/b; a%b; a^b;\ncondition ? valueA : valueB',[['arithmetic','+ − * / % and ^ for exponentiation; unary + and − are supported.'],['comparisons','< <= > >= == != produce booleans.'],['logical','&&, || and ! combine or negate conditions.'],['ternary','condition ? trueValue : falseValue returns one expression.'],['vectors / matrices','Vector addition is component-wise. A scalar can scale a vector. Vector × vector is a dot product; compatible matrix products are supported.']],[
'Use parentheses when precedence could be unclear. Division by zero or an invalid domain can produce unusable numeric values that later fail as dimensions. OpenSCAD does not use + for string concatenation; use str().',
'Vectors are ordinary lists with numeric entries. Multiplication is not element-by-element vector multiplication: write a comprehension for that. Matrix shapes must be compatible. Equality compares values and structure; small floating-point errors may require a tolerance comparison such as abs(a-b)<0.001.'],['A range [0:5] is not the same as the list [0,5].'],[ex('Choose a size with a condition')],['lists','math','types']),
topic('lists','Lists, ranges and indexing','Language',['[]','ranges','.x','.y','.z'],'Store points, dimensions and sequences for repeated geometry.','values=[a,b,c];\nvalues[0]; values.x;\n[start:end]; [start:step:end];',[['index','Zero-based. .x, .y and .z are convenient component access for the first three elements.'],['range','Start, optional step, and inclusive endpoint if reached by the step. Negative steps count down.'],['nested lists','Represent points, tables, faces and matrices.']],[
'A list may contain mixed types or other lists, but geometric coordinates require valid numbers. len() measures a list or string. Out-of-range indexing yields undef rather than a new element. A range is a sequence description used by loops and comprehensions.',
'Avoid enormous ranges: they can generate more geometry than the browser can handle. For circular repetition, use [0:n-1] rather than including n, which duplicates the first location.'],['Use concat() to combine lists; adding two numeric vectors adds components.'],[ex('Posts with different heights')],['for','comprehensions','concat']),
topic('for','for — repeat geometry','Language',['for'],'Generate an instance for each value or combination of values.','for(i=[start:step:end]) shape();\nfor(x=[...],y=[...]) shape();',[['iterators','Range or list; multiple iterators generate the Cartesian product.']],[
'Each iteration has its own variable value; it does not mutate a shared counter. The generated shapes are normally combined. Use a loop as a set of cutters inside difference() for bolt circles, vents and perforations.',
'Keep the last angular index at count−1 to avoid a duplicate at 360 degrees. intersection_for() is the separate operation for intersecting iterations rather than combining them.'],['A loop can create disconnected pieces. Add a base or overlap if you need one printable part.'],[ex('A six-hole bolt circle')],['comprehensions','intersection','recipe-flange']),
topic('if','if / else — choose geometry','Language',['if','else'],'Select which geometry to generate based on a condition.','if(condition) shapeA(); else shapeB();',[['condition','A boolean expression, commonly a parameter comparison.']],[
'if is used when you want to include or omit modules. For values within an expression, use the ternary operator. Braces make the intended grouping clearer when several shapes belong to a branch.',
'Nested if statements can attach an else to the nearest unmatched if; use braces to avoid ambiguity.'],['An omitted branch can leave a difference or intersection empty.'],[ex('Optional centre hole')],['operators','variables','assert']),
topic('let','let — local intermediate calculations','Language',['let','assign'],'Bind local values for a module or expression.','let(a=expression,b=a*2) shape();\nfunction f(x)=let(y=x*x) y+1;',[['bindings','Evaluated in order within let, so later bindings can refer to earlier ones.']],[
'Use let() to name a calculation without changing the surrounding scope. This is useful inside a loop, a function or a comprehension. It makes formulas readable and avoids repeated expressions.',
'assign() appears in older scripts but is deprecated and is not a supported modelling route in this bundled engine. Replace it with let(); do not assume sequential mutation semantics.'],['let() creates local bindings; it does not update outer variables.'],[ex('Local dimensions for each post')],['variables','functions','for']),
topic('modules','module — reusable geometry','Language',['module'],'Name a reusable piece of geometry with parameters and defaults.','module name(parameter=default, ...) { geometry; }\nname(parameter=value);',[['parameters','Positional arguments follow declaration order; named arguments are clearer for long calls.'],['defaults','Used when the caller omits that parameter.']],[
'A module emits geometry; it does not return a numeric value. Define parts such as a foot, bracket, hole pattern or profile once, then call them with different dimensions. Keep the module’s origin consistent and document where its base or centre lies.',
'A module may accept child geometry through children(). Use a function instead when you need to calculate a number, point or list. include/use makes modules reusable across source files.'],['Do not end a module declaration with an accidental geometry call; definition and invocation are separate.'],[ex('A reusable hollow post')],['children','functions','include-use']),
topic('children','children and $children — geometry wrappers','Language',['children','$children','parent_module'],'Write modules that transform, duplicate or combine child geometry.','children(); children(0); children([0,2]);\n$children; parent_module(index);',[['children()','Instantiate all child statements supplied to the calling module.'],['index / list / range','Select particular children by zero-based index.'],['$children','Number of supplied child statements.'],['parent_module(index)','Return a module name from the call hierarchy, useful for diagnostics.']],[
'This is how you build wrappers such as “repeat this shape around a circle”. A single child statement can itself generate many objects; $children counts statements, not the final mesh components.',
'Use assert($children>0,...) when a module requires input. Parent inspection is primarily a debugging tool; avoid coupling geometry to particular caller names.'],['children(0) and children() are different when several children were supplied.'],[ex('A circular repeater')],['modules','for','assert']),
topic('functions','function — calculations and function values','Language',['function'],'Calculate reusable values without directly producing geometry.','function name(x)=expression;\nf=function(x) x*2;\ny=f(3);',[['return value','A single expression; use let and ternary expressions to structure it.'],['function values','Anonymous functions can be stored, passed to other functions and tested with is_function().']],[
'Functions can return numbers, points, lists, strings or other values. They are ideal for deriving dimensions, building point lists and encoding formulas. Modules use those results to emit geometry.',
'Recursive functions need a terminating condition. Prefer comprehensions for a straightforward map or filter. Functional OpenSCAD does not provide a general imperative while loop or mutable list append.'],['Recursion and huge generated lists still consume browser resources.'],[ex('A calculated star profile')],['comprehensions','let','types']),
topic('comprehensions','List comprehensions — generate, filter and flatten','Language',['each'],'Build lists from expressions rather than creating geometry directly.','[for(i=sequence) expression]\n[for(i=sequence) if(test) expression]\n[for(i=sequence) let(x=...) expression]\n[each listA, each listB]\n[for(i=0; i<5; i=i+1) i]',[],[
'A comprehension returns a list. A module for loop emits geometry. Combine them by generating polygon points or a table, then passing the list to a geometric module. Conditions filter results; an if/else comprehension can choose between two values.',
'each flattens one level by splicing elements into the surrounding result. Without it, you retain nested lists. The C-style comprehension form defines iteration bindings, a continuation test and next values; it is not a general mutable loop statement.'],['A comprehension can still generate an impractically large list; keep resolution bounded.'],[ex('Filtered circular points')],['lists','functions','for']),
topic('math','abs, sign, min and max','Numbers and data',['abs','sign','min','max'],'Constrain and compare numerical dimensions.','abs(x); sign(x); min(a,b,...); max(a,b,...);\nmin(list); max(list);',[['abs(x)','Magnitude without the sign.'],['sign(x)','−1 for negative, 0 for zero, 1 for positive.'],['min / max','Choose the smallest/largest value from arguments or a list.']],[
'Use min and max to clamp user parameters to useful ranges: max(minimum,min(maximum,value)). abs() gives a distance from a signed difference, while sign() can select a direction. Empty or inappropriate inputs do not make useful geometric dimensions.'],['Clamping is helpful for a preview, but assert() is clearer when an invalid input should be rejected.'],[ex('Clamp a safe wall thickness')],['rounding','assert','operators']),
topic('trig','sin, cos, tan and inverse trigonometry','Numbers and data',['sin','cos','tan','asin','acos','atan'],'Calculate circular points, slopes and angles in degrees.','sin(a); cos(a); tan(a); asin(x); acos(x); atan(x);',[['sin / cos / tan','Input angle in degrees.'],['asin / acos','Return degrees; input must lie between −1 and 1 for a real result.'],['atan','Return the angle corresponding to a slope; use atan2 for a vector direction.']],[
'A point on a circle of radius r is [r*cos(a),r*sin(a)]. This produces bolt circles, wave profiles and rotationally repeated geometry. Multiplying by PI/180 is only needed when interfacing with a formula that specifically expects radians.',
'tan() grows without bound near 90 degrees plus multiples of 180. Guard such dimensions before using them in solids.'],['Floating-point rounding can put a normalised dot product slightly outside ±1; clamp it before acos().'],[ex('A triangular wedge from a slope')],['atan2','norm-cross','functions']),
topic('atan2','atan2 — angle from a direction','Numbers and data',['atan2'],'Recover a planar direction angle while preserving its quadrant.','atan2(y,x);',[['y, x','The components of the direction vector, in this order.']],[
'atan(y/x) loses quadrant information and divides by zero when x is zero. atan2(y,x) handles ordinary axis-aligned directions and chooses the correct quadrant. Use it to point a repeated part toward a target in XY.'],['The zero vector has no useful direction; check its length first.'],[ex('Align a bar with a vector')],['rotate','norm-cross','trig']),
topic('rounding','floor, ceil and round','Numbers and data',['floor','ceil','round'],'Convert dimensions or counts to integer steps.','floor(x); ceil(x); round(x);',[['floor','Largest integer no greater than x.'],['ceil','Smallest integer no smaller than x.'],['round','Nearest integer. Avoid relying on tie behavior for exact manufacturing rules.']],[
'Use floor to fit a whole number of repeats into a span, ceil to ensure coverage, and round for a nearest-grid choice. Rounding to a step s can be written round(x/s)*s.'],['Counts must still be positive; floor of a small ratio can be zero.'],[ex('Fit posts along a span')],['math','for']),
topic('powers','pow, sqrt, exp, ln and log','Numbers and data',['pow','sqrt','exp','ln','log'],'Evaluate powers, roots and logarithmic relationships.','pow(x,y); sqrt(x); exp(x); ln(x); log(x);',[['pow(x,y)','x raised to y; x^y is the operator form.'],['sqrt(x)','Nonnegative square root; x must be nonnegative.'],['exp(x)','e raised to x.'],['ln(x)','Natural logarithm, for x>0.'],['log(x)','Base-10 logarithm, for x>0.']],[
'These functions are useful for dimensions derived from geometry or growth laws. For a right triangle, sqrt(a*a+b*b) gives the hypotenuse. Invalid domains can propagate unusable values into a later modelling operation.'],['Check domain constraints with assert before generating geometry.'],[ex('Size a diagonal brace')],['assert','atan2','operators']),
topic('norm-cross','norm and cross — vector geometry','Numbers and data',['norm','cross'],'Measure vector length and form perpendicular directions.','norm(v); cross(a,b);',[['norm','Euclidean length of a numeric vector.'],['cross','3D vector cross product. For two 2D vectors, returns their signed scalar cross product.']],[
'Normalising v means v/norm(v), provided the length is nonzero. The cross product’s direction follows the right-hand rule and its magnitude is related to the area spanned by the inputs. Parallel vectors have a zero cross product.',
'Use vectors to compute lengths and orientations for braces, supports and custom transforms. Dot products use vector multiplication, a*b.'],['A zero-length axis cannot define a useful rotation.'],[ex('A cylinder rotated around a computed axis')],['multmatrix','atan2','operators']),
topic('rands','rands — repeatable random values','Numbers and data',['rands'],'Generate a list of random numbers, optionally with a fixed seed.','rands(min_value,max_value,value_count,seed);',[['bounds','Minimum and maximum values.'],['value_count','Number of values to produce.'],['seed','Use a fixed seed for repeatable geometry. Omit for a changing result.']],[
'Store the returned list once and index it. Repeated unseeded calls can change the model during each preview. A fixed seed is valuable for reproducible textures, irregular patterns and examples.'],['Random values do not guarantee printable clearances; bound and validate dimensions.'],[ex('Repeatable varying posts')],['lists','for']),
topic('concat','len and concat — list size and combination','Numbers and data',['len','concat'],'Measure a list/string or join values into a list.','len(value); concat(a,b,...);',[['len','Number of elements in a list or characters in a string.'],['concat','Combine supplied lists and scalar values into a new list, flattening their top level.']],[
'concat([1,2],[3,4]) gives [1,2,3,4]. It does not recursively flatten every nested level. Use each inside a comprehension when you want to splice a generated list. len() makes loops adapt to a list rather than hard-coding its length.'],['String concatenation uses str(), not concat().'],[ex('Combine two point lists')],['lists','comprehensions','str']),
topic('lookup','lookup — interpolate a table','Numbers and data',['lookup'],'Interpolate a numeric value between sampled [key,value] pairs.','lookup(key, [[key0,value0],[key1,value1],...]);',[['key','Position to evaluate.'],['table','Pairs defining a piecewise-linear relationship; keep keys ordered and unique for clarity.']],[
'Use lookup for a radius-vs-height profile or a dimension table that should interpolate smoothly. Between entries, the result is linear; it is not a spline. Out-of-range queries use the end values rather than extending the slope.'],['Do not confuse lookup with search: lookup interpolates values, while search finds positions.'],[ex('A sampled turned profile')],['search','rotate-extrude','concat']),
topic('search','search — find matching indices','Numbers and data',['search'],'Find positions of values or characters in strings, lists or table columns.','search(match,table,num_returns_per_match=1,index_col_num=0);',[['match','Value or list of values to search for. A string may be treated as characters.'],['table','String, list or list of rows.'],['num_returns_per_match','How many matches per query; 0 requests all.'],['index_col_num','Column to compare when searching rows.']],[
'The result is a list of indices, not the matching values. Searching multiple values can produce nested lists, especially when requesting all matches. Use echo to inspect the result before indexing a table, and handle missing matches.',
'For numeric interpolation rather than exact matches, use lookup().'],['List wrapping matters when searching for a complete string rather than its characters.'],[ex('Find a size in a list')],['lookup','lists','diagnostics']),
topic('str','str, chr and ord — strings and characters','Numbers and data',['str','chr','ord'],'Build labels and convert between characters and character codes.','str(value,...); chr(code_or_list); ord(string);',[['str','Concatenate string representations of values.'],['chr','Convert a code point, list or range of code points into a string.'],['ord','Return the code point of the first character.']],[
'str() is the normal way to combine text with numeric parameters. Use it for embossed dimension labels, part numbers and diagnostic messages. chr() can generate sequences of characters; the selected font must contain the requested glyphs.',
'Escape quotes and backslashes inside string literals. Use \\n for a newline where supported; text layout may be clearer as separate positioned text() calls.'],['The language string and the available font are separate: a valid character code can still lack a glyph.'],[ex('A numbered label')],['text','textmetrics','diagnostics']),
topic('types','Type tests — validate reusable inputs','Numbers and data',['is_undef','is_bool','is_num','is_string','is_list','is_function','is_object'],'Inspect values without assuming their type.','is_undef(x); is_bool(x); is_num(x); is_string(x);\nis_list(x); is_function(x); is_object(x);',[
['is_undef','True for an undefined value. Useful for optional parameters.'],['is_bool / is_num','Distinguish booleans from numeric values.'],['is_string / is_list','Identify textual and list inputs.'],['is_function','Recognise a function value.'],['is_object','Recognise built-in objects such as metric results in this newer engine.']],[
'Type predicates return true or false. Combine them with assert() to reject invalid input before it reaches a geometry operation. A list type alone does not prove that it contains the right number of numeric coordinates.',
'An optional parameter can default to undef and select an alternative using is_undef(value). That is clearer than relying on a missing variable warning.'],['Do not treat “is a number” as proof that a dimension is positive or finite; validate its range too.'],[ex('A checked module')],['assert','variables','functions']),
topic('textmetrics','textmetrics and fontmetrics — measure lettering','Numbers and data',['textmetrics','fontmetrics'],'Obtain text bounds and font measurements for automatic label sizing.','textmetrics(text,size,font,halign,valign,spacing,direction,language,script);\nfontmetrics(size,font);',[['textmetrics result','Object with fields such as position, size, ascent, descent, offset and advance.'],['fontmetrics result','Font-wide measurements including ascent/descent and spacing information. Use echo to inspect the returned object.']],[
'Text size is nominal. textmetrics().size reports the actual bounding dimensions of the shaped string, while position locates that box relative to the text origin. advance describes cursor movement and need not equal the visible width.',
'Use the same font, size, spacing and alignment options in both the metric call and text(). Font substitution changes both measurements and geometry.'],['An empty string can have empty visible bounds. Add padding and a minimum plate size for automatic labels.'],[ex('A plate sized to its label')],['text','str','recipe-label']),
topic('assert','assert — fail early with a useful message','Files and diagnostics',['assert'],'Validate a parameter or relationship before generating geometry.','assert(condition,"message");\nassert(condition,"message") shape();\nfunction f(x)=assert(x>0,"Positive x required") sqrt(x);',[['condition','Must be true to continue.'],['message','Optional explanation; use str() to include values.']],[
'Assertions are ideal for wall thickness, hole spacing, positive dimensions and required child counts. A failed assertion stops rendering, so the original workshop model remains unchanged. Include a useful remedy in the message rather than a generic failure.'],['A valid mesh does not automatically imply a physically printable wall thickness. Encode your own design constraints.'],[ex('Reject an impossible wall')],['types','diagnostics','recipe-box']),
topic('diagnostics','echo, render and error recovery','Files and diagnostics',['echo','render'],'Inspect values, request rendering and recover from common failures.','echo(value, name=value);\nrender(convexity=...) geometry();',[['echo','Print values in diagnostics; does not create geometry. It can also appear within an expression.'],['render','Force evaluation of a subtree in desktop preview; the studio already performs a rendered-solid calculation.']],[
'Use echo to inspect a point list, computed radius, table search or metrics object. Diagnostic output is bounded in RetroPaint, and echoed text containing “ERROR:” is not itself an engine error.',
'A syntax error selects the reported file and line. A missing include or asset means the dependency was not loaded at the expected relative path. An empty result often comes from a cutter consuming all material or an intersection with no overlap. A pure 2D result needs extrusion. Non-manifold output usually needs a modelling correction rather than a higher convexity value.',
'If a render is slow, reduce resolution, avoid unnecessarily detailed Minkowski kernels, and simplify repeated booleans. Cancel stops the current job. The scene is not changed by a failed preview.'],['The studio’s Preview is not desktop OpenCSG F5. render() cannot restore desktop-only highlighting or colour.'],[ex('Inspect a computed dimension')],['limits','assert','resolution']),
topic('include-use','include and use — multi-file projects','Files and diagnostics',['include','use'],'Reuse source files while controlling whether top-level statements execute.','include <path/file.scad>\nuse <path/file.scad>',[],[
'include brings in the referenced source, including top-level assignments and geometry. use makes module and function definitions available without instantiating that file’s top-level example geometry. Do not expect a caller-visible constant assignment to be imported by use; pass configuration as parameters or use include appropriately.',
'Load the containing folder to retain nested relative paths. Entry script determines what renders; Edit file determines which source you are changing. Supplied files are kept with the applied model. MCAD is bundled and can be addressed as MCAD/filename.scad.',
'OpenSCAD is not a browser JavaScript environment. include/use refer to virtual project files, not arbitrary files on the computer or automatic Internet downloads. Add external libraries explicitly.'],['Avoid circular includes and conflicting module names from several libraries.'],[ex('A library without its demo geometry',{'parts/foot.scad':'// Define a tapered foot, with a default height of 6 mm.\nmodule foot(h=6){\n  cylinder(h=h,r1=6,r2=4,$fn=32); // Wide base, narrower top.\n}\n// A standalone library demo: use ignores this; include runs it.\nfoot(100);'})],['workflow','modules','mcad']),
topic('import','import — SVG, DXF and mesh assets','Files and diagnostics',['import'],'Bring geometry into a script from a supplied project asset.','import(file="part.stl", convexity=1);\nimport(file="outline.svg", center=false, dpi=96);',[['file','Relative asset path. Mesh formats supported by the engine include STL, OFF, OBJ, AMF and 3MF; 2D imports include SVG and DXF.'],['center / origin / scale','Positioning and scaling options vary with file format.'],['dpi','SVG conversion when dimensions use pixels rather than explicit physical units.'],['id / layer','Select SVG elements or layers / DXF layers where supported.'],['convexity','Desktop visibility hint, not a mesh repair control.']],[
'A mesh import is 3D and can be joined, cut or transformed directly. SVG/DXF imports are 2D and normally need extrusion. Closed SVG paths describe filled areas; an open drawing stroke is not automatically a solid wall.',
'Supply the file through Open folder or Add files. A missing file stops the studio render. Imported meshes must ultimately form valid closed solids to transfer back into the workshop. Do not assume the file’s units match millimetres; inspect dimensions and use scale() if needed.'],['This module is different from the experimental import() value-returning function.','External references embedded inside an SVG are not a substitute for supplying self-contained geometry.'],[ex('Extrude an SVG asset',{'outline.svg':'<svg xmlns="http://www.w3.org/2000/svg" width="24mm" height="16mm" viewBox="0 0 24 16">\n  <!-- First loop is the outer rectangle; second loop is the hole. -->\n  <!-- Even-odd filling leaves the nested loop empty. -->\n  <path d="M0 0 H24 V16 H0 Z M8 4 V12 H16 V4 Z" fill-rule="evenodd"/>\n</svg>'})],['linear-extrude','scale','workflow']),
topic('surface','surface — height maps','Make solids from profiles',['surface'],'Create terrain or a relief from a numeric grid or PNG image.','surface(file="grid.dat", center=false, invert=false, convexity=1);',[['file','DAT text grid or PNG asset supplied with the project.'],['center','Centre the grid in XY.'],['invert','Reverse the height mapping for an image input.'],['convexity','Desktop preview hint.']],[
'A DAT file contains rows of heights separated by whitespace. Grid positions define X and Y; values define elevation. PNG input derives heights from the image intensity. The result includes a base and sides, so it can form a solid.',
'Scale the resulting geometry to control its physical footprint and relief depth. Large height maps can create many triangles very quickly, so reduce image resolution before importing.'],['Transparent/image-background handling may not match your desired physical base; inspect the generated bounds.'],[ex('A small terrain tile',{'heights.dat':'1 1 1 1\n1 4 3 1\n1 2 5 1\n1 1 1 1\n'})],['scale','import','limits']),
topic('version','version and version_num — engine checks','Files and diagnostics',['version','version_num'],'Inspect the engine version when writing portable libraries.','version(); version_num(); version_num([year,month,day]);',[['version()','Returns the engine’s version components as a list.'],['version_num()','Returns a comparable numeric version representation; an optional version vector can be converted too.']],[
'A script may use a version check to choose compatible syntax or explain a minimum requirement. Code studio is bundled with a specific OpenSCAD build; desktop installations can differ in features and experimental switches.',
'Version alone does not prove that an experimental feature is enabled. Consult the compatibility topic and test the relevant operation.'],['Do not silently substitute a different geometry algorithm just because a version check fails; explain the limitation.'],[ex('Report the bundled engine')],['experimental','limits']),
topic('special','Special variables and desktop camera controls','Language',['$t','$preview','$vpr','$vpt','$vpd','$vpf'],'Separate modelling settings from desktop preview state.','$preview; $t; $vpr; $vpt; $vpd; $vpf;',[
['$preview','False during the rendered-solid calculation used here.'],['$t','Desktop animation time, conventionally 0–1. The studio does not animate it.'],['$vpr / $vpt','Desktop viewport rotation / translation. They do not control the studio’s orbit camera.'],['$vpd / $vpf','Desktop view distance / field of view, likewise not the studio camera.']],[
'Use ordinary parameters to generate a particular pose or stage of an animated design. You can assign a fixed value for a calculation, but there is no animation timeline in Code studio. Drag the preview to orbit and use Fit preview to frame the model.',
'$fn, $fa and $fs affect tessellation and do work here. $children applies inside wrapper modules.'],['A script that generates geometry only when $preview is true may render empty here.'],[ex('Choose a fixed pose')],['resolution','children','limits']),
topic('experimental','Experimental and legacy names','Files and diagnostics',['roof','object','has_key','dxf_dim','dxf_cross','child','import_stl','import_dxf','import_off','dxf_linear_extrude','dxf_rotate_extrude'],'Recognise names that require special handling instead of assuming universal availability.','roof(method="voronoi") profile();\nobject(key=value); has_key(object,"key");\nvalue=import("data.json");',[['roof','Experimental roof-generation module in upstream builds; not enabled as a studio modelling feature.'],['object / has_key','Experimental generic-object construction and inspection; not enabled here. is_object and text/font metrics objects are separate available features.'],['value-returning import','Experimental data import function; the ordinary geometry import module is supported.'],['dxf_dim / dxf_cross','Legacy DXF drawing queries that require appropriate entities in a supplied DXF file. Prefer explicit parameters for new designs.'],['child / assign','Old control names: use children() and let().'],['import_stl / import_dxf / import_off','Historical forms: use import(file).'],['dxf_linear_extrude / dxf_rotate_extrude','Historical workflows: import a 2D profile, then use linear_extrude or rotate_extrude.']],[
'A development build may contain a feature behind a command-line flag. Code studio does not enable every experimental extension. Unknown-module or unknown-function diagnostics should be investigated; adding a new function name to a script cannot activate an unavailable engine feature.',
'Use the supported alternative where practical. For a roof, build a triangular prism from a polygon and extrusion. For configuration data, use lists and functions or an included .scad file. External libraries may define their own helpers, which are not core language methods.'],['The wiki distinguishes the supported core from these compatibility notes. Experimental syntax below is explanatory, not an enabled feature.'],[ex('A roof without experimental features')],['polygon','linear-extrude','include-use','types'],'Compatibility reference'),
topic('limits','Compatibility and workshop limits','Files and diagnostics',[],'Know which results can become editable workshop solids.','OpenSCAD 2026.10.27 · Manifold backend · rendered STL transfer',[],[
'The studio runs the real OpenSCAD language engine, but it is not the desktop GUI. Desktop OpenCSG preview, animation, per-face colours, highlighting and desktop filesystem paths are not reproduced. Resulting geometry must be a valid closed 3D solid; isolated 2D output needs extrusion.',
'Current limits are 2 MB of UTF-8 source, 2,000 supplied files totalling 20 MB, a five-minute render timeout, 200,000 transferred triangles and coordinates within ±10,000 mm. A project can be valid in desktop OpenSCAD and still exceed these browser/workshop limits.',
'Code studio’s standard MCAD library and Noto Sans font are available locally. Other libraries and exact fonts must be supplied with the project. Experimental features are listed separately. All wiki examples labelled Preview example are intended to produce a solid in this bundled configuration.'],['Physical manufacturing still needs appropriate wall thickness, clearances and scale.'],[],['resolution','diagnostics','workflow','experimental']),
topic('recipe-flange','Recipe: a parametric drilled flange','Worked projects',[],'Use parameters, a bolt-circle loop and subtractive cutters for a mechanical plate.','difference() { disk(); centre_bore(); bolt_circle(); }',[],[
'Choose the outside radius, thickness, centre bore radius, bolt-circle radius and number of holes as independent parameters. Ensure the holes leave material at the outside edge and do not overlap the centre bore.',
'The loop rotates a translated cutter around the origin. Each cutter starts below the disk and finishes above it. Preview, change the constants under Parameters, then Add to scene.'],['Set a fixed $fn for predictable hole tessellation.'],[ex('Six-hole flange')],['for','cylinder','difference','assert']),
topic('recipe-box','Recipe: an open box with controlled walls','Worked projects',[],'Subtract an inner cavity while leaving the base intact.','difference() { outer_box(); raised_inner_cutter(); }',[],[
'Place the outer box at Z=0. Offset the inner cavity by the wall thickness in X, Y and Z. Make the cavity cutter tall enough to pass through the top. Its bottom sets the base thickness.',
'For a lid or press-fit insert, add a separate clearance parameter. Do not assume zero-clearance parts will assemble after manufacturing.'],['Check wall < min(width,depth)/2 and base < height.'],[ex('Open storage tray')],['cube','difference','offset']),
topic('recipe-pocket','Recipe: a pocket, boss and through-hole','Worked projects',[],'Combine additive and subtractive features on a common base.','difference() { union() { base(); boss(); } pocket(); hole(); }',[],[
'Build the base and overlapping boss together inside union(), making them one stock child. Then subtract the shallow pocket and through-hole. The pocket’s starting Z controls its depth; the hole cutter extends completely through the assembly.',
'Keep cuts in a single difference where possible so the material/cutter distinction stays visible. Once added, the result is also usable by the workshop’s Join and Cut tools.'],['A boss touching the base without overlap can be fragile at the seam.'],[ex('Feature plate')],['union','difference','coordinates']),
topic('recipe-rounded','Recipe: a rounded mounting plate','Worked projects',[],'Choose between a cheap 2D rounded outline and full 3D edge rounding.','linear_extrude(h) offset(r) profile();\nminkowski() { block(); sphere(r); }',[],[
'Offset or hull followed by extrusion rounds the outline but keeps the top and bottom edges sharp. Minkowski with a sphere rounds all edges and costs more. Compensate the starting box dimensions for the amount added by the rounding kernel.',
'After rounding the stock, subtract the mounting holes. This keeps their diameter independent of the rounding operation.'],['If only plan-view corner rounding is required, prefer a 2D construction.'],[ex('Rounded plate with two holes')],['minkowski','offset','hull']),
topic('recipe-bowl','Recipe: design a revolved vessel','Worked projects',[],'Build the entire wall and base from one cross-section.','rotate_extrude(angle=360) polygon(profile);',[],[
'Sketch the cross-section in radius/height coordinates. Begin on the axis at the bottom, move outward along the base, up the outside wall, across the lip, down the inside wall, then back to the axis above the base.',
'The separation between inside and outside lines controls wall thickness. An angled wall measured horizontally does not have the same thickness normal to the wall; account for that when dimensional accuracy matters.'],['Do not cross the axis or reverse the profile into a self-intersection.'],[ex('A straight-walled cup')],['rotate-extrude','polygon','coordinates']),
topic('recipe-label','Recipe: automatic raised or engraved labels','Worked projects',[],'Measure text and place it on a supporting plate.','m=textmetrics(label,...);\nlinear_extrude(depth) text(label,...);',[],[
'Use identical font settings for measurement and geometry. Add padding around m.position and m.size to construct a supporting plate. Raise letters so their bottom overlaps the top of the plate by a small amount.',
'To engrave instead, subtract the text extrusion from the plate and position it so it cuts only the desired depth. All text-related geometry uses the supplied font, so bundle the exact font if the outline must be reproducible.'],['Separate dots must overlap the base just like the rest of the letters.'],[ex('Engraved component label')],['text','textmetrics','difference']),
topic('mcad','MCAD library: reusable mechanical parts','Libraries',['MCAD'],'Use the bundled library and browse every supplied source file and declaration.','use <MCAD/boxes.scad>\nroundedCube([30,20,8],r=3,sidesonly=true,center=true);',[],[
'MCAD is a collection of independent .scad libraries, not extra core language keywords. Import the specific file that defines the part you need. Two files may use the same module name with different arguments, so avoid combining overlapping namespaces blindly.',
'The MCAD source catalogue in this wiki lists every supplied .scad file, its module/function declarations and the original commented source. Use its exact signatures and comments when calling less common helpers. Some old files contain deprecated constructs or demonstrations; use generally avoids instantiating their top-level examples.',
'Start with boxes for rounded stock, nuts_and_bolts for hole cutters, bearing for bearing envelopes, and involute_gears for gear generation. These libraries have their own conventions for units, origin, tolerances and resolution. Inspect a generated part before depending on its nominal fit.'],['Library models are design aids, not certified dimensions for a purchased component.'],[ex('A bundled rounded box'),ex('A hexagonal nut recess')],['include-use','workflow','limits']),
];
